content.css:
/* ========================================================================== */
/* BFUSION Task KPI Board — Modernised panel/card chrome (rkpi-aligned)       */
/* ========================================================================== */
.bfusion-root {
  width: 100%;
  height: 100%;
  overflow: auto;
  font-family: var(--tkb-font-family, "Segoe UI"), wf_segoe-ui_normal, helvetica, arial, sans-serif;
  background-color: #FFFFFF;
  position: relative;
  color: #1F2937;
}
.bfusion-root *,
.bfusion-root *:before,
.bfusion-root *:after {
  box-sizing: border-box;
}
.bfusion-root.tkb-root {
  display: flex;
  flex-direction: column;
  padding-bottom: 24px;
  /* license badge clear-zone */
}
/* ========================================================================== */
/* Header bar (title + subtitle + status pulse + info button)                 */
/* ========================================================================== */
.tkb-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 18px 8px 18px;
  border-bottom: 1px solid #E5E7EB;
  background: #FFFFFF;
  position: relative;
}
.tkb-header__titles {
  flex: 1 1 auto;
  min-width: 0;
}
.tkb-header__title {
  font-weight: 700;
  color: #1F2937;
  letter-spacing: 0.1px;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: var(--tkb-fs-header-title, 13px);
}
.tkb-header__subtitle {
  margin-top: 2px;
  color: #6B7280;
  font-weight: 400;
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: var(--tkb-fs-header-subtitle, 10px);
}
.tkb-header__status {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 999px;
  background: #F8FAFC;
  border: 1px solid #E5E7EB;
  font-size: var(--tkb-fs-header-status, 11px);
  font-weight: 600;
  color: #6B7280;
  flex-shrink: 0;
}
.tkb-header__status-text {
  white-space: nowrap;
}
.tkb-header__info {
  flex: 0 0 auto;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1px solid #E5E7EB;
  background: #fff;
  color: #6B7280;
  font-style: italic;
  font-weight: 700;
  font-size: 11px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
  transition: all 0.15s ease;
}
.tkb-header__info:hover {
  color: #fff;
  background: #E8612A;
  border-color: #E8612A;
  transform: scale(1.05);
}
.tkb-header__info-pop {
  position: absolute;
  top: calc(100% + 6px);
  right: 12px;
  z-index: 30;
  width: 340px;
  max-width: calc(100% - 24px);
  background: #fff;
  border: 1px solid #E5E7EB;
  border-radius: 8px;
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.12);
  padding: 12px 14px;
  color: #1F2937;
  line-height: 1.45;
  font-size: var(--tkb-fs-sub, 11px);
}
.tkb-header__info-pop ul {
  margin: 8px 0 0 0;
  padding-left: 18px;
}
.tkb-header__info-pop ul li {
  margin: 3px 0;
  color: #6B7280;
}
.tkb-info-pop__title {
  font-weight: 700;
  color: #1F2937;
  margin-bottom: 4px;
  border-bottom: 2px solid #E8612A;
  padding-bottom: 4px;
}
.tkb-info-pop__desc {
  color: #6B7280;
  margin-top: 6px;
}
/* Pulse dot inside the status pill */
.tkb-pulse {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  display: inline-block;
}
.tkb-pulse--healthy {
  background: #10B981;
  box-shadow: 0 0 0 0 rgba(16, 185, 129, 0.6);
  animation: tkb-pulse 2.4s infinite;
}
.tkb-pulse--warning {
  background: #F59E0B;
  box-shadow: 0 0 0 0 rgba(245, 158, 11, 0.6);
  animation: tkb-pulse 1.6s infinite;
}
.tkb-pulse--critical {
  background: #EF4444;
  box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.6);
  animation: tkb-pulse 1s infinite;
}
@keyframes tkb-pulse {
  0% {
    box-shadow: 0 0 0 0 currentColor;
    opacity: 1;
  }
  70% {
    box-shadow: 0 0 0 8px transparent;
    opacity: 0.8;
  }
  100% {
    box-shadow: 0 0 0 0 transparent;
    opacity: 1;
  }
}
/* ========================================================================== */
/* Main wrapper + body grid                                                   */
/* ========================================================================== */
.tkb-wrap {
  width: 100%;
  padding: 14px 18px 4px 18px;
  background: #FFFFFF;
}
.tkb-body {
  display: grid;
  grid-template-columns: 1fr 260px;
  gap: 14px;
  align-items: start;
}
.tkb-main {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 14px;
}
/* ========================================================================== */
/* Section panel — grey gradient head + body (rkpi pattern)                   */
/* ========================================================================== */
.tkb-panel {
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
  border-radius: 8px;
  overflow: hidden;
}
.tkb-panel__head {
  background: linear-gradient(90deg, #F1F4F8 0%, #E9EEF4 100%);
  color: #1F2937;
  padding: 10px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-bottom: 1px solid #E5E7EB;
}
.tkb-panel__title {
  font-size: var(--tkb-fs-panel-title, 12px);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: #1F2937;
}
.tkb-panel__head-sub {
  font-size: var(--tkb-fs-panel-sub, 11px);
  color: #6B7280;
  font-weight: 500;
  text-align: right;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 60%;
}
.tkb-panel__body {
  padding: 14px 16px 16px 16px;
  background: #FFFFFF;
}
/* ========================================================================== */
/* Hero panel — attention ring + 3 big counters                               */
/* ========================================================================== */
.tkb-hero {
  display: flex;
  flex-direction: row;
  align-items: center;
  gap: 20px;
}
.tkb-hero__ring {
  flex-shrink: 0;
}
.tkb-hero__ring svg {
  display: block;
}
.tkb-hero__ring-pct {
  font-weight: 700;
  font-family: "Segoe UI", system-ui, sans-serif;
  font-size: var(--tkb-fs-ring-pct, 26px);
}
.tkb-hero__ring-sub {
  fill: #6B7280;
  text-transform: uppercase;
  letter-spacing: 1px;
  font-weight: 600;
  font-size: var(--tkb-fs-ring-sub, 10px);
}
.tkb-hero__counts {
  display: flex;
  flex-direction: row;
  align-items: stretch;
  gap: 24px;
  flex: 1;
  min-width: 0;
}
.tkb-hero__count {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-width: 0;
  border-left: 1px solid #E5E7EB;
  padding-left: 20px;
}
.tkb-hero__count:first-child {
  border-left: 0;
  padding-left: 0;
}
.tkb-hero__count-value {
  font-weight: 700;
  line-height: 1;
  color: #1F2937;
  letter-spacing: -0.5px;
  font-variant-numeric: tabular-nums;
  font-size: var(--tkb-fs-hero-value, 30px);
}
.tkb-hero__count-label {
  color: #6B7280;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  font-weight: 700;
  margin-top: 6px;
  font-size: var(--tkb-fs-hero-label, 11px);
}
.tkb-hero__count-sub {
  color: #9CA3AF;
  margin-top: 2px;
  font-size: var(--tkb-fs-hero-sub, 11px);
}
/* ========================================================================== */
/* Modern KPI Card — top-band design (rkpi pattern)                           */
/* ========================================================================== */
.tkb-strip {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
  gap: 10px;
}
.tkb-card {
  --tkb-card-color: #1F2A44;
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
  border-radius: 8px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: box-shadow 0.2s ease, transform 0.15s ease;
  min-height: 118px;
}
.tkb-card:hover {
  box-shadow: 0 4px 14px rgba(15, 23, 42, 0.08);
  transform: translateY(-1px);
}
.tkb-card__band {
  background: var(--tkb-card-color);
  color: #FFFFFF;
  padding: 8px 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  min-height: 30px;
}
.tkb-card__band-title {
  font-size: var(--tkb-fs-card-label, 11px);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.tkb-card__band-meta {
  font-size: var(--tkb-fs-card-band-meta, 10px);
  font-weight: 600;
  color: rgba(255, 255, 255, 0.85);
  white-space: nowrap;
}
.tkb-card__body {
  padding: 12px 14px 12px 14px;
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}
.tkb-card__value {
  font-size: var(--tkb-fs-card-value, 24px);
  font-weight: 700;
  line-height: 1.1;
  color: #1F2937;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.tkb-card__unit {
  font-size: var(--tkb-fs-card-unit, 11px);
  color: #6B7280;
  font-weight: 500;
  margin-left: 4px;
}
.tkb-card__sub {
  font-size: var(--tkb-fs-card-sub, 11px);
  color: #6B7280;
  line-height: 1.4;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.tkb-card__pbar {
  margin-top: auto;
  height: 4px;
  background: #F1F5F9;
  border-radius: 2px;
  overflow: hidden;
}
.tkb-card__pbar-fill {
  height: 100%;
  border-radius: 2px;
  background: var(--tkb-card-color);
  transition: width 0.3s ease;
}
/* ========================================================================== */
/* Health distribution bar — inside .tkb-panel                                */
/* ========================================================================== */
.tkb-healthbar {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.tkb-healthbar__subtitle {
  font-size: var(--tkb-fs-healthbar-sub, 11px);
  color: #6B7280;
  margin-bottom: 2px;
}
.tkb-healthbar__track {
  width: 100%;
  height: 22px;
  background: #F1F5F9;
  border-radius: 6px;
  overflow: hidden;
  display: flex;
  box-shadow: inset 0 0 0 1px rgba(15, 23, 42, 0.02);
}
.tkb-healthbar__seg {
  height: 100%;
  transition: width 0.3s ease;
  display: flex;
  align-items: center;
  justify-content: center;
}
.tkb-healthbar__seg:hover {
  opacity: 0.85;
}
.tkb-healthbar__seg-label {
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.15);
}
.tkb-healthbar__legend {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}
.tkb-legend {
  font-size: var(--tkb-fs-healthbar-sub, 11px);
  color: #1F2937;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 500;
}
.tkb-legend strong {
  font-weight: 700;
  color: #1F2937;
  font-variant-numeric: tabular-nums;
}
.tkb-legend__dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
  flex-shrink: 0;
}
.tkb-legend__count {
  color: #1F2937;
  font-weight: 700;
  margin-left: 2px;
  font-variant-numeric: tabular-nums;
}
/* ========================================================================== */
/* Attention Banner                                                           */
/* ========================================================================== */
.tkb-banner {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border-radius: 8px;
  font-size: var(--tkb-fs-banner, 12px);
  line-height: 1.4;
  border: 1px solid transparent;
}
.tkb-banner__icon {
  font-size: 16px;
  flex-shrink: 0;
  line-height: 1;
  color: var(--banner-color, #6B7280);
}
.tkb-banner__text {
  color: #1F2937;
}
.tkb-banner__text strong {
  color: var(--banner-color, #1F2937);
  font-weight: 700;
}
.tkb-banner--ok {
  background: rgba(5, 150, 105, 0.06);
  border-color: rgba(5, 150, 105, 0.2);
}
.tkb-banner--warning {
  background: rgba(217, 119, 6, 0.06);
  border-color: rgba(217, 119, 6, 0.22);
}
.tkb-banner--critical {
  background: rgba(220, 38, 38, 0.06);
  border-color: rgba(220, 38, 38, 0.22);
}
/* ========================================================================== */
/* Insights side rail — wrapped in .tkb-panel                                 */
/* ========================================================================== */
.tkb-rail {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.tkb-rail__divider {
  margin-top: 6px;
  padding-top: 8px;
  border-top: 1px dashed #E5E7EB;
  font-size: var(--tkb-fs-rail-divider, 10px);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: #6B7280;
  margin-bottom: 2px;
}
.tkb-insight {
  display: flex;
  flex-direction: row;
  gap: 8px;
  padding: 8px 10px;
  background: #F8FAFC;
  border-radius: 6px;
  border: 1px solid #E5E7EB;
  border-left: 3px solid #E5E7EB;
}
.tkb-insight--info {
  border-left-color: #3b82f6;
}
.tkb-insight--success {
  border-left-color: #059669;
}
.tkb-insight--warning {
  border-left-color: #d97706;
}
.tkb-insight--critical {
  border-left-color: #dc2626;
}
.tkb-insight__icon {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: #fff;
  border: 1px solid #E5E7EB;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
  color: #1F2937;
  flex-shrink: 0;
}
.tkb-insight--info .tkb-insight__icon {
  background: rgba(59, 130, 246, 0.1);
  color: #2563eb;
  border-color: rgba(59, 130, 246, 0.3);
}
.tkb-insight--success .tkb-insight__icon {
  background: rgba(5, 150, 105, 0.1);
  color: #059669;
  border-color: rgba(5, 150, 105, 0.3);
}
.tkb-insight--warning .tkb-insight__icon {
  background: rgba(217, 119, 6, 0.1);
  color: #d97706;
  border-color: rgba(217, 119, 6, 0.3);
}
.tkb-insight--critical .tkb-insight__icon {
  background: rgba(220, 38, 38, 0.1);
  color: #dc2626;
  border-color: rgba(220, 38, 38, 0.3);
}
.tkb-insight__body {
  min-width: 0;
  flex: 1;
}
.tkb-insight__label {
  font-size: var(--tkb-fs-insight-headline, 11px);
  font-weight: 700;
  color: #1F2937;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  line-height: 1.3;
}
.tkb-insight__text {
  font-size: var(--tkb-fs-insight-detail, 10px);
  color: #6B7280;
  line-height: 1.4;
  margin-top: 2px;
}
/* Insight rail collapse strip (24px) */
.tkb-rail-strip {
  width: 24px;
  background: linear-gradient(180deg, #FFFFFF 0%, #F8FAFC 100%);
  border: 1px solid #E5E7EB;
  border-radius: 8px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  padding: 8px 0;
}
.tkb-rail-strip:hover {
  background: #F8FAFC;
}
.tkb-rail-strip__arrow {
  color: #E8612A;
  font-size: 12px;
  font-weight: 700;
  line-height: 1;
}
.tkb-rail-strip__label {
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  color: #6B7280;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1px;
  text-transform: uppercase;
}
/* ========================================================================== */
/* Responsive                                                                 */
/* ========================================================================== */
.tkb-root.tkb-medium .tkb-body {
  grid-template-columns: 1fr 220px;
}
.tkb-root.tkb-medium .tkb-hero__count-value {
  font-size: var(--tkb-fs-hero-value, 24px);
}
.tkb-root.tkb-medium .tkb-hero__ring svg {
  width: 120px;
  height: 120px;
}
.tkb-root.tkb-narrow .tkb-body {
  grid-template-columns: 1fr;
}
.tkb-root.tkb-narrow .tkb-hero {
  flex-direction: column;
  align-items: flex-start;
}
.tkb-root.tkb-narrow .tkb-hero__counts {
  width: 100%;
  gap: 14px;
  flex-wrap: wrap;
}
.tkb-root.tkb-narrow .tkb-hero__count {
  padding-left: 12px;
}
.tkb-root.tkb-narrow .tkb-hero__count:first-child {
  padding-left: 0;
}
.tkb-root.tkb-narrow .tkb-strip {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
/* ========================================================================== */
/* Landing Page (shared pattern)                                              */
/* ========================================================================== */
.bfusion-landing-wrap {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background-color: #FFFFFF;
}
.bfusion-landing {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 420px;
  padding: 20px;
  box-sizing: border-box;
  text-align: center;
}
.bfusion-landing__logo-container {
  width: 130px;
  height: 84px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #E8612A;
  border-radius: 12px;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.08);
  margin-bottom: 24px;
  overflow: hidden;
}
.bfusion-landing__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.bfusion-landing__text-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}
.bfusion-landing__title {
  font-size: 15px;
  font-weight: 600;
  color: #242424;
  margin: 0 0 14px 0;
  padding: 0;
  line-height: 1.2;
}
.bfusion-landing__description {
  font-size: 11.5px;
  font-weight: 400;
  color: #666666;
  margin: 0;
  padding: 0;
  line-height: 1.5;
}
.bfusion-landing__description strong {
  font-weight: 600;
  color: #444444;
}
.bfusion-landing__separator {
  width: 60%;
  height: 1px;
  background-color: #EAEAEA;
  margin: 20px 0;
}
.bfusion-landing__metadata {
  font-size: 10.5px;
  color: #8C8C8C;
  margin-bottom: 4px;
  font-weight: 400;
  line-height: 1.4;
}
.bfusion-landing__metadata strong {
  font-weight: 600;
  color: #707070;
}
/* ========================================================================== */
/* License Badge & Watermark                                                  */
/* ========================================================================== */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: rgba(5, 150, 105, 0.08);
  border: 1px solid rgba(5, 150, 105, 0.25);
  color: #059669;
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
.bfusion-watermark {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 15;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
  background: repeating-linear-gradient(-45deg, transparent, transparent 120px, rgba(220, 38, 38, 0.03) 120px, rgba(220, 38, 38, 0.03) 122px);
}
.bfusion-watermark__content {
  text-align: center;
  opacity: 0.18;
  user-select: none;
  transform: rotate(-18deg);
}
.bfusion-watermark__title {
  font-size: 56px;
  font-weight: 900;
  color: #DC2626;
  letter-spacing: 12px;
  line-height: 1;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__subtitle {
  font-size: 16px;
  font-weight: 600;
  color: #DC2626;
  margin-top: 6px;
  letter-spacing: 3px;
  text-transform: uppercase;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__link {
  font-size: 11px;
  color: #9CA3AF;
  margin-top: 12px;
  font-family: "Segoe UI", sans-serif;
}
/* ========================================================================== */
/* Empty Data State                                                           */
/* ========================================================================== */
.bfusion-empty {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
}
.bfusion-empty__message {
  font-size: 12px;
  color: #94a3b8;
  font-weight: 400;
  text-align: center;
  letter-spacing: 0.2px;
}
